class SafeCache {
    private val mutex = Mutex()
    private val cache = mutableMapOf<String, User>()

    suspend fun put(key: String, user: User) = mutex.withLock {
        cache[key] = user
    }

    suspend fun get(key: String): User? = mutex.withLock { cache[key] }
}

val dbChanges = Channel<Unit>()
val pushEvents = Channel<Unit>()

suspend fun syncWorker() {
    while (true) {
        select<Unit> {
            dbChanges.onReceive { syncFromLocal() }
            pushEvents.onReceive { syncFromRemote() }
        }
    }
}
